export function getAvailableJobUpgrades(job, activeUpgrades = []) {
  const tree = JOB_UPGRADES_BY_ROLE[job] || [];
  return tree.filter(u => !activeUpgrades.includes(u.id) && (!u.requires || activeUpgrades.includes(u.requires)));
}

export function getEligibleQuests(day, completedQuests = [], activeQuests = []) {
  return QUESTS.filter(q => {
    if (completedQuests.includes(q.id) || activeQuests.includes(q.id)) return false;
    const prereqs = q.prerequisites || {};
    if (prereqs.minDay && day < prereqs.minDay) return false;
    if (prereqs.requiredQuests && !prereqs.requiredQuests.every(id => completedQuests.includes(id))) return false;
    return true;
  });
}
